const raw = $input.first().json.output || $input.first().json.text || '';

// Extract JSON array from response (handle markdown code fences)
let jsonStr = raw;
const fenceMatch = raw.match(/```(?:json)?\s*([\s\S]*?)```/);
if (fenceMatch) {
  jsonStr = fenceMatch[1].trim();
}

// Try to find array brackets if not already clean
const arrayMatch = jsonStr.match(/(\[[\s\S]*\])/);
if (arrayMatch) {
  jsonStr = arrayMatch[1];
}

let strategies;
try {
  strategies = JSON.parse(jsonStr);
} catch (e) {
  return [{
    json: {
      error: 'Failed to parse Ollama output as JSON',
      raw_output: raw.substring(0, 500),
      parse_error: e.message
    }
  }];
}

if (!Array.isArray(strategies)) {
  strategies = [strategies];
}

const enriched = strategies.map(s => ({
  json: {
    strategy_name: s.strategy_name || 'unnamed',
    one_sentence: s.one_sentence || '',
    python_code: s.python_code || '',
    params: s.params || {},
    symbol: 'ES',
    timeframe: '15min',
    start_date: '2024-01-01',
    end_date: '2024-12-31',
    source: 'ollama'
  }
}));

return enriched;

const items = $input.all();

// Filter out untitled/empty scout results
const validIdeas = items.filter(item => {
  const title = item.json.title || item.json.name || '';
  const desc = item.json.description || item.json.summary || '';
  if (!title.trim() || title.toLowerCase() === 'untitled' || title.trim().length < 10) return false;
  if (!desc.trim() || desc.trim().length < 20) return false;
  return true;
});

if (validIdeas.length === 0) {
  return [{ json: { scoutContext: '\nNo high-quality research discoveries available for this cycle.', scoutedIdeaCount: 0 } }];
}

const lines = validIdeas.slice(0, 5).map((item, i) => {
  const source = item.json.source || 'web';
  const title = (item.json.title || item.json.name || 'Untitled').slice(0, 100);
  const desc = (item.json.description || item.json.summary || '').slice(0, 200);
  return `${i + 1}. [${source}] ${title}: ${desc}`;
});

return [{
  json: {
    scoutContext: `\n\nRecent research discoveries to consider when generating strategies:\n${lines.join('\n')}`,
    scoutedIdeaCount: validIdeas.length
  }
}];

// Pre-flight blocked this strategy because a prior quantum_mc_run produced UCI > threshold.
// Tier 6: cache-READ-ONLY gate. The strategy is dropped from this cycle to avoid
// re-running an already-failed prop-firm UCI test. Counts as a graveyard signal.
const input = $input.first().json;
return [{
  json: {
    skipped: true,
    reason: 'quantum_pre_flight_failed',
    score: input.score,
    qmcRunId: input.qmcRunId,
    backtestId: input.backtestId,
    threshold: input.threshold,
    workflowRunId: input.workflowRunId
  }
}];

